      const task=suggestion.confirmed&&state.tasks.find(t=>t.id===suggestion.targetId),d=task||suggestion.data||{},project=state.projects.find(p=>p.id===d.projectId),module=P.modules(project).find(m=>m.id===d.moduleId);
