  function confirmAI(i){
    const msg=state.aiMessages[i];if(!msg?.action||msg.confirmed)return;const a=msg.action;if(a.type==='event'&&!a.data.date){editAI(i);showToast('请补充日程日期后保存');return;}
    if(a.data.projectId&&!state.projects.some(p=>p.id===a.data.projectId)){editAI(i);$('#form-error').textContent='关联项目已不存在，请重新选择后保存。';return;}
    if(a.type==='task'&&a.data.moduleId&&!P.modules(state.projects.find(p=>p.id===a.data.projectId)).some(m=>m.id===a.data.moduleId)){editAI(i);$('#form-error').textContent='所属模块已发生变化，请重新选择后保存。';return;}
    if(a.type==='event'&&a.data.time&&a.data.endTime&&a.data.endTime<=a.data.time){editAI(i);$('#form-error').textContent='结束时间应晚于开始时间，请修改后保存。';return;}
    const item={...a.data,id:uid(),updatedAt:new Date().toLocaleString('zh-CN'),...(a.type==='task'?{done:false}:{}),...(a.type==='project'?{status:'planning'}:{}),...(a.type==='note'?{moduleScope:'unassigned'}:{})};
    if(a.type==='project'){try{TaxonomyModel.prepare(state,'projects',item);}catch(err){editAI(i);$('#form-error').textContent=err.message;return;}}
    if(a.type==='note'){try{D.validate(item);if(item.resourceType==='web'&&state.notes.some(n=>(n.projectId||'')===(item.projectId||'')&&D.kind(n)==='web'&&n.url===item.url))throw Error('这个链接已收藏，请修改草稿或打开已有文档。');}catch(err){editAI(i);$('#form-error').textContent=err.message;return;}}
    if(!commitTraining(next=>{W.saveRecord(next,a.type,item);W.completeAssistantAction(next,i,a.type,item.id);} ))return;
    render();showToast('已写入工作台，可点击「打开'+actionLabel(a)+'」查看');
  }
